package bg.tuvarna.sit.project.ps.internshipmanagement.service;
import bg.tuvarna.sit.project.ps.internshipmanagement.dto.*;import bg.tuvarna.sit.project.ps.internshipmanagement.dto.admin.*;import bg.tuvarna.sit.project.ps.internshipmanagement.entity.enums.Role;import bg.tuvarna.sit.project.ps.internshipmanagement.mapper.*;import bg.tuvarna.sit.project.ps.internshipmanagement.repository.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class AdminService{private final UserRepository users;private final CompanyRepository companies;private final StudentProfileRepository students;private final InternshipOfferRepository offers;private final ApplicationRepository apps;private final CompanyRegistrationRequestRepository requests;private final UserMapper um;private final CompanyMapper cm;private final StudentProfileMapper sm;private final InternshipOfferMapper om;private final ApplicationMapper am;public AdminService(UserRepository u,CompanyRepository c,StudentProfileRepository s,InternshipOfferRepository o,ApplicationRepository a,CompanyRegistrationRequestRepository r,UserMapper um,CompanyMapper cm,StudentProfileMapper sm,InternshipOfferMapper om,ApplicationMapper am){users=u;companies=c;students=s;offers=o;apps=a;requests=r;this.um=um;this.cm=cm;this.sm=sm;this.om=om;this.am=am;}public List<UserDto> users(){return users.findAll().stream().map(um::toDto).toList();}public UserDto setEnabled(Long id,Boolean enabled){var u=users.findById(id).orElseThrow(()->new bg.tuvarna.sit.project.ps.internshipmanagement.exception.ResourceNotFoundException("User not found"));u.setEnabled(enabled);return um.toDto(users.save(u));}public List<CompanyDto> companies(){return companies.findAll().stream().map(cm::toDto).toList();}public List<StudentProfileDto> students(){return students.findAll().stream().map(sm::toDto).toList();}public List<InternshipOfferDto> offers(){return offers.findAll().stream().map(om::toDto).toList();}public List<ApplicationDto> applications(){return apps.findAll().stream().map(am::toDto).toList();}public SystemStatsDto stats(){return SystemStatsDto.builder().users(users.count()).students(students.count()).companies(companies.count()).pendingCompanyRequests(requests.findByStatus(bg.tuvarna.sit.project.ps.internshipmanagement.entity.enums.CompanyRegistrationStatus.PENDING).size()).internshipOffers(offers.count()).activeOffers(offers.findByStatus(bg.tuvarna.sit.project.ps.internshipmanagement.entity.enums.OfferStatus.ACTIVE).size()).applications(apps.count()).build();}}
